const imageReplacements = {
  'photo-1610189012906-4c3f3e8edc1d': 'photo-1610030469983-98e550d6193c',
  'photo-1583391733956-6c78276477e7': 'photo-1594736797933-d0501ba2fe65',
  'photo-1577083552431-6e5fd01988d5': 'photo-1549490349-8643362247b5'
}
const normalizeImage = (url, fallback) => {
  if (!url) return fallback
  return Object.entries(imageReplacements).reduce((current, [invalid, replacement]) => current.replace(invalid, replacement), url)
}
const img = (p, fallback = 'https://images.unsplash.com/photo-1610701596007-11502861dcfa?auto=format&fit=crop&w=900&q=85') => normalizeImage(p?.thumbnail || p?.images?.[0]?.url, fallback)
const money = (n) => `₹${Number(n || 0).toLocaleString('en-IN')}`
const offerRates = [10, 15, 20, 25, 30]
const discountPercent = (p) => Math.min(30, Math.max(0, Number(p?.discountPercent ?? offerRates[parseInt(String(p?._id || '0').slice(-1), 16) % offerRates.length])))
const salePrice = (p) => Math.round(Number(p?.price || 0) * (1 - discountPercent(p) / 100))
const ratingValue = (p) => Number(p?.rating || 0).toFixed(2)
const shareProduct = async (product) => {
  const url = `${window.location.origin}/products/${product._id}`
  if (navigator.share) {
    await navigator.share({ title: product.title, text: `Have a look at ${product.title} on KarigarConnect.`, url })
    return 'shared'
  }
  await navigator.clipboard.writeText(url)
  return 'copied'
}
